const p = $input.first().json;
const d = p.normalized_data;
const model = $env.OPENAI_MODEL || 'gpt-4o-mini';

let systemPrompt, userPrompt;

if (p.production_type === 'cattle') {
  systemPrompt = 'You are FincApp\'s agricultural AI analyst specializing in cattle production for Colombian and Latin American livestock operations. Respond ONLY with valid JSON — no markdown, no explanation.';
  userPrompt = `Analyze this cattle farm sync report and return a structured risk and recommendation assessment.

Farm ID: ${p.farm_id}
Owner ID: ${p.owner_id}
Sync Timestamp: ${p.sync_timestamp}

Production Data:
- Head count: ${d.head_count}
- Average weight: ${d.average_weight_kg} kg
- Pregnant animals: ${d.pregnancy_count}
- Feeding efficiency: ${d.feeding_efficiency_pct !== null ? d.feeding_efficiency_pct + '%' : 'N/A'}
- Active health alerts: ${d.health_alert_count}
- Alert details: ${JSON.stringify(d.health_alerts)}

Return a JSON object with this exact structure:
{
  "risk_level": "low | medium | high",
  "summary": "<one sentence operational summary>",
  "recommendations": ["<action 1>", "<action 2>"],
  "predicted_yield_kg": <number or null>,
  "alerts_requiring_action": ["<alert description>"]
}`;

} else if (p.production_type === 'swine') {
  systemPrompt = 'You are FincApp\'s agricultural AI analyst specializing in swine (porcine) production for Colombian and Latin American operations. Respond ONLY with valid JSON — no markdown, no explanation.';
  userPrompt = `Analyze this swine farm sync report and return a structured risk and recommendation assessment.

Farm ID: ${p.farm_id}
Owner ID: ${p.owner_id}
Sync Timestamp: ${p.sync_timestamp}

Production Data:
- Head count: ${d.head_count}
- Average weight: ${d.average_weight_kg} kg
- Animals in gestation: ${d.gestation_count}
- Mortality rate: ${d.mortality_rate_pct !== null ? d.mortality_rate_pct + '%' : 'N/A'}
- Feed conversion ratio: ${d.feed_conversion_ratio !== null ? d.feed_conversion_ratio : 'N/A'}
- Active health alerts: ${d.health_alert_count}
- Alert details: ${JSON.stringify(d.health_alerts)}

Return a JSON object with this exact structure:
{
  "risk_level": "low | medium | high",
  "summary": "<one sentence operational summary>",
  "recommendations": ["<action 1>", "<action 2>"],
  "predicted_yield_kg": <number or null>,
  "alerts_requiring_action": ["<alert description>"]
}`;

} else {
  systemPrompt = 'You are FincApp\'s agricultural AI analyst specializing in poultry (avícola) production for Colombian and Latin American operations. Respond ONLY with valid JSON — no markdown, no explanation.';
  userPrompt = `Analyze this poultry farm sync report and return a structured risk and recommendation assessment.

Farm ID: ${p.farm_id}
Owner ID: ${p.owner_id}
Sync Timestamp: ${p.sync_timestamp}

Production Data:
- Flock size: ${d.flock_size} birds
- Average weight: ${d.average_weight_kg} kg
- Egg production: ${d.egg_production_count} units
- Mortality rate: ${d.mortality_rate_pct !== null ? d.mortality_rate_pct + '%' : 'N/A'}
- Feed conversion ratio: ${d.feed_conversion_ratio !== null ? d.feed_conversion_ratio : 'N/A'}
- Active health alerts: ${d.health_alert_count}
- Alert details: ${JSON.stringify(d.health_alerts)}

Return a JSON object with this exact structure:
{
  "risk_level": "low | medium | high",
  "summary": "<one sentence operational summary>",
  "recommendations": ["<action 1>", "<action 2>"],
  "predicted_yield_kg": <number or null>,
  "alerts_requiring_action": ["<alert description>"]
}`;
}

return [{
  json: {
    ...p,
    llm_request_body: {
      model,
      response_format: { type: 'json_object' },
      temperature: 0.2,
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user',   content: userPrompt }
      ]
    }
  }
}];

const response = $input.first().json;
const upstream = $('Build Prompt').first().json;

if (!response.choices || response.choices.length === 0) {
  throw new Error('LLM returned no choices — check OPENAI_API_KEY and OPENAI_MODEL env vars');
}

let analysis;
try {
  analysis = JSON.parse(response.choices[0].message.content);
} catch (e) {
  throw new Error(`LLM response is not valid JSON: ${response.choices[0].message.content}`);
}

const required = ['risk_level', 'summary', 'recommendations', 'alerts_requiring_action'];
for (const field of required) {
  if (!(field in analysis)) {
    throw new Error(`LLM response missing expected field: '${field}'`);
  }
}

const validRisk = ['low', 'medium', 'high'];
if (!validRisk.includes(analysis.risk_level)) {
  throw new Error(`LLM returned invalid risk_level: '${analysis.risk_level}'`);
}

return [{
  json: {
    owner_id: upstream.owner_id,
    farm_id: upstream.farm_id,
    production_type: upstream.production_type,
    sync_timestamp: upstream.sync_timestamp,
    analysis,
    llm_model: response.model,
    tokens_used: response.usage?.total_tokens ?? null
  }
}];
